#include <stdint.h>
#include "stm32f407xx.h"


#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

void RCC_Config(void)
{

	RCC->CR |= (1 << 16);
	while(!(RCC->CR & (1 << 17)));
	RCC->CR |= (1 << 19);
	RCC->CR &= ~(1 << 24);

	RCC->PLLCFGR &= ~(1 << 22);
	RCC->PLLCFGR |= (1 << 22);
	RCC->PLLCFGR &= ~(0x3F << 0);
	RCC->PLLCFGR |= (4 << 0);
	RCC->PLLCFGR &= ~(0x1FF << 6);
	RCC->PLLCFGR |= (0xAB << 6);
	RCC->PLLCFGR &= ~(3 << 16);

	RCC->CR |= (1 << 24);
	while(!(RCC->CR & (1 << 25)));

	// 5. FLASH AYARLARI (ÇÖKMEYİ ENGELLEYEN KRİTİK ADIM)
	// 168 MHz ve 3.3V için 5 Wait State gerekir. Ayrıca Prefetch ve Cache'ler açılmalıdır.
	FLASH->ACR = FLASH_ACR_ICEN | FLASH_ACR_DCEN | FLASH_ACR_PRFTEN | FLASH_ACR_LATENCY_5WS;

	RCC->CFGR &= ~(0xF << 4);
	RCC->CFGR |= (5 << 10);
	RCC->CFGR |= (4 << 13);

	RCC->CFGR |= (2 << 0);
	while((RCC->CFGR & (3 << 2)) != (2 << 2));

	RCC->CR &= ~(1 << 0);
}

void GPIO_Config(void)
{

	RCC->AHB1ENR |= (1 << 2);
	RCC->AHB1ENR |= (1 << 3);
	RCC->AHB1ENR |= (1 << 0);

	GPIOA->MODER |= (3 << 0);
	GPIOA->MODER |= (3 << 2);
	GPIOA->MODER |= (3 << 6);
	GPIOD->MODER |= (0x55 << 0);
	GPIOC->MODER &= ~(3 << 0);



}


void ADC_Config()
{
	RCC->APB2ENR |= (1 << 8);
	ADC->CCR |= (1 << 16);

	ADC1->CR1 |= (2 << 24);
	ADC1->CR1 |= (1 << 8);
	ADC1->CR2 |= (1 << 0);
	ADC1->CR2 |= (1 << 10);   // EOCS: Her dönüşümden sonra EOC bayrağını tetikle

	ADC1->SMPR2 |= (3 << 0);    // Kanal 0 (PA0) için 56 Cycle
	ADC1->SMPR2 |= (3 << 3);	// Kanal 1 (PA1) için 56 Cycle
	ADC1->SMPR2 |= (3 << 9); 	// Kanal 3 (PA3) için 56 Cycle

	ADC1->SQR1 |= (2 << 20);

	ADC1->SQR3 |= (3 << 0) | (0 << 5) | (1 << 10);
}

uint8_t Read_ADC()
{
	uint8_t value;

	ADC1->SQR3 &= ~(0x1F << 0);   // SQ1 e kanal 0'i atadım

	ADC1->CR2 |= (1 << 30);    //SWSTRT (start conversion of regular channels) dönüştürme işlemini başlatır;

	while(!(ADC1->SR & (1 << 1)));

	value = ADC1->DR;

	return value;
}

void Read_ADC_All(uint8_t* sicaklik, uint8_t* ana_guc, uint8_t* yedek_guc)
{
	ADC1->CR2 |= (1 << 30);    // Çevrimi Başlat

	// 1. Kanalı (SQ1 -> PA3) bekle ve oku
	while(!(ADC1->SR & (1 << 1)));
	*sicaklik = ADC1->DR;

	// 2. Kanalı (SQ2 -> PA0) bekle ve oku
	while(!(ADC1->SR & (1 << 1)));
	*ana_guc = ADC1->DR;

	// 3. Kanalı (SQ3 -> PA1) bekle ve oku
	while(!(ADC1->SR & (1 << 1)));
	*yedek_guc = ADC1->DR;
}


int main(void)
{
	RCC_Config();
	GPIO_Config();
	ADC_Config();


    /* Loop forever */
	while(1)
	{


		if(GPIOC->IDR & (1 << 0))
		{
			uint8_t ntc, pot1, pot2;
			Read_ADC_All(&ntc, &pot1, &pot2);

			// 1. ÖNCELİK: KRİTİK DURUM (Motor çok sıcak VEYA Ana İtki/Güç çok düşük)
						if(ntc > 150 || pot1 < 50)
						{
							GPIOD->ODR &= ~(0xF << 0);         // Önce tüm pinleri sıfırla
							GPIOD->ODR |= (1 << 2) | (1 << 3); // Kırmızı LED (PD2) ve Buzzer (PD3) çalışsın
						}
						// 2. ÖNCELİK: UYARI DURUMU (Kritik hata yok AMA Yedek Güç zayıflıyor)
						else if(pot2 < 100)
						{
							GPIOD->ODR &= ~(0xF << 0);         // Önce tüm pinleri sıfırla
							GPIOD->ODR |= (1 << 1);            // Sadece Sarı LED (PD1) çalışsın (Uyarı)
						}
						// 3. ÖNCELİK: NORMAL DURUM (Tüm değerler güvenli sınırda)
						else
						{
							GPIOD->ODR &= ~(0xF << 0);         // Önce tüm pinleri sıfırla
							GPIOD->ODR |= (1 << 0);            // Sadece Yeşil LED (PD0) çalışsın
						}

		}
		else
		{
			GPIOD->ODR &= ~(0xF << 0);
			GPIOD->ODR |= (1 << 2);

		}

	}
}
